import{_ as t,o as a,c as s,a5 as i}from"./chunks/framework.DGp912Ge.js";const g=JSON.parse('{"title":"Target Go — Python Example","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"software/sdk/python/target-go.md","filePath":"software/sdk/python/target-go.md","lastUpdated":1783328958000}'),o={name:"software/sdk/python/target-go.md"};function n(r,e,l,h,p,d){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="target-go-—-python-example" tabindex="-1">Target Go — Python Example <a class="header-anchor" href="#target-go-—-python-example" aria-label="Permalink to &quot;Target Go — Python Example&quot;">​</a></h1><p><strong>Source</strong>: <code>rbq_sdk/python/example/sport/rbq_target_go.py</code></p><p>Python port of the C++ <a href="/RBQ/software/sdk/cpp/target-go.html">Target Go</a>. Commands the robot to <strong>walk to a target pose</strong> (x, y, heading) with a chosen gait by publishing a single <code>TargetGo</code> message on <code>rt/rbq/cmd/target_go</code>.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><ol><li>Reads <code>interface</code> and optional <code>x y theta gait mode</code> from the command line.</li><li>Calls <code>ChannelFactoryInitialize(0, interface)</code>, then creates <code>ChannelPublisher(&quot;rt/rbq/cmd/target_go&quot;, TargetGo_)</code>.</li><li>Waits ~0.5 s for DDS discovery, fills the <code>TargetGo_</code> message, publishes <strong>once</strong>, prints what it sent, and exits.</li></ol><p>The on-robot <strong>QuadWalk</strong> locomotion engine subscribes to the topic and executes the walk.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li><code>rbq_sdk_py</code> importable — see <a href="/RBQ/software/sdk/python/overview.html">Python SDK Overview</a>.</li><li>Robot stack running (simulator or hardware) on the same DDS interface.</li><li><strong>The robot must be powered on / in control and standing first.</strong> Otherwise QuadWalk rejects the command with <code>Can&#39;t Receive cmd: CON_START first</code>.</li></ul><h2 id="run" tabindex="-1">Run <a class="header-anchor" href="#run" aria-label="Permalink to &quot;Run&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> RBQ/rbq_sdk/python/example/sport</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rbq_target_go.py</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">networkInterfac</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [x] [y] [theta_deg] [gait] [mode]</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># simulator, 1 m forward with wave gait:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rbq_target_go.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lo</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1.0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span></span></code></pre></div><p>Arguments, gaits and modes are identical to the <a href="/RBQ/software/sdk/cpp/target-go.html#run">C++ version</a>. Use the same interface as the running robot/sim (see the <a href="/RBQ/software/sdk/cpp/image-echo.html">Image Echo</a> interface note — <code>lo</code> is often not multicast-capable).</p><h2 id="example-output" tabindex="-1">Example output <a class="header-anchor" href="#example-output" aria-label="Permalink to &quot;Example output&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[rbq_target_go] published: gait=0 mode=0 x=1.0 y=0.0 theta=0.0</span></span></code></pre></div><p>Verified against the MuJoCo simulator — QuadWalk receives the command on <code>rt/rbq/cmd/target_go</code> (it logs <code>Can&#39;t Receive cmd: CON_START first</code> until control is started, then walks).</p>`,14)])])}const k=t(o,[["render",n]]);export{g as __pageData,k as default};
